const cwd = "/Users/pfleidi/entire/cli/.entire/worktrees/pfleidi-cor-1430-cli-enable-async-mirror-creation-by-default";
const head = "d6990ae1e7cb04748cc16d41692c289cc7f9d360";
const gql = `query($owner: String!, $repo: String!, $number: Int!, $threadCursor: String) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      reviewThreads(first: 100, after: $threadCursor) {
        nodes {
          id isResolved path line
          comments(first: 100) {
            nodes { id databaseId body author { __typename login } createdAt updatedAt }
            pageInfo { hasNextPage endCursor }
          }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}`;
const calls = [
  ["requested", tools.exec_command({cmd:"gh api repos/entireio/cli/pulls/2246/requested_reviewers",workdir:cwd,yield_time_ms:10000,max_output_tokens:8000,sandbox_permissions:"require_escalated",justification:"Allow read-only GitHub reviewer-state intake?"})],
  ["reviews", tools.exec_command({cmd:"gh api repos/entireio/cli/pulls/2246/reviews --paginate",workdir:cwd,yield_time_ms:10000,max_output_tokens:15000,sandbox_permissions:"require_escalated",justification:"Allow read-only GitHub completed-review intake?"})],
  ["comments", tools.exec_command({cmd:"gh api repos/entireio/cli/issues/2246/comments --paginate",workdir:cwd,yield_time_ms:10000,max_output_tokens:15000,sandbox_permissions:"require_escalated",justification:"Allow read-only GitHub PR-comment intake?"})],
  ["commit", tools.exec_command({cmd:`gh api repos/entireio/cli/commits/${head}`,workdir:cwd,yield_time_ms:10000,max_output_tokens:8000,sandbox_permissions:"require_escalated",justification:"Allow read-only GitHub head timestamp intake?"})],
  ["threads", tools.exec_command({cmd:"gh api graphql -F owner=entireio -F repo=cli -F number=2246 -F threadCursor=null -f query='"+gql.replaceAll("'","'\\''")+"'",workdir:cwd,yield_time_ms:10000,max_output_tokens:20000,sandbox_permissions:"require_escalated",justification:"Allow read-only GitHub review-thread intake?"})],
  ["trail_show", tools.exec_command({cmd:"entire trail show 1225 --repo gh/entireio/cli",workdir:cwd,yield_time_ms:10000,max_output_tokens:10000,sandbox_permissions:"require_escalated",justification:"Allow read-only Entire trail context intake?"})],
  ["approvals", tools.exec_command({cmd:"entire trail approvals 1225 --repo gh/entireio/cli --json",workdir:cwd,yield_time_ms:10000,max_output_tokens:10000,sandbox_permissions:"require_escalated",justification:"Allow read-only Entire approval intake?"})],
  ["trail_comments", tools.exec_command({cmd:"entire trail comment list --trail 1225 --repo gh/entireio/cli --all --json",workdir:cwd,yield_time_ms:10000,max_output_tokens:20000,sandbox_permissions:"require_escalated",justification:"Allow read-only Entire discussion intake?"})],
  ["findings", tools.exec_command({cmd:"entire trail finding list 1225 --repo gh/entireio/cli --status open --freshness current --json --limit 100",workdir:cwd,yield_time_ms:10000,max_output_tokens:20000,sandbox_permissions:"require_escalated",justification:"Allow read-only Entire current-finding intake?"})],
  ["diff", tools.exec_command({cmd:"git diff origin/main HEAD",workdir:cwd,yield_time_ms:10000,max_output_tokens:30000})]
];
const results = await Promise.all(calls.map(async ([label,p]) => [label, await p]));
for (const [label,r] of results) text(`---${label} (exit ${r.exit_code ?? "running"})---\n${r.output}`);

